using Notifications.Legacy;

namespace Notifications;

/// <summary>Sends email messages.</summary>
public sealed class EmailClient
{
    private readonly IMailSender _mailSender;

    public EmailClient(IMailSender mailSender)
    {
        _mailSender = mailSender ?? throw new ArgumentNullException(nameof(mailSender));
    }

    public async Task<bool> SendEmailAsync(Message message, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(message);
        return await _mailSender.SendAsync(
            message.Recipient.EmailAddress,
            message.Subject,
            message.Body,
            cancellationToken);
    }
}

public interface IMailSender
{
    Task<bool> SendAsync(string address, string subject, string body, CancellationToken cancellationToken = default);
}
